#include <cuda_runtime.h>
#include <cmath>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <map>
#include <string>
#include <vector>
constexpr int H=2560,S=160,T=256,WARPS=8,K=10;
static double g_shared_read_s=0.0,g_shared_cuda_s=0.0;
void ck(cudaError_t e,const char*w){if(e!=cudaSuccess){fprintf(stderr,"%s: %s\n",w,cudaGetErrorString(e));exit(1);}}
#define CK(x) ck((x),#x)
template<class T>std::vector<T>rf(const std::string&p,size_t n){auto t=std::chrono::steady_clock::now();std::vector<T>v(n);std::ifstream f(p,std::ios::binary);f.read((char*)v.data(),n*sizeof(T));if(!f||f.peek()!=EOF){fprintf(stderr,"bad file %s\n",p.c_str());exit(1);}g_shared_read_s+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count();return v;}
template<class T>T*up(const std::vector<T>&v){auto t=std::chrono::steady_clock::now();T*p=nullptr;CK(cudaMalloc(&p,v.size()*sizeof(T)));CK(cudaMemcpy(p,v.data(),v.size()*sizeof(T),cudaMemcpyHostToDevice));g_shared_cuda_s+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count();return p;}
struct Weights{uint16_t*g,*u,*d,*gate;};struct Work{float*x,*hidden,*partial,*scale;cudaStream_t stream;};struct Req{int layer;std::vector<float>x;std::vector<int32_t>ids;std::vector<float>routes;};
__device__ float bf(uint16_t x){return __uint_as_float(uint32_t(x)<<16);}__device__ float ws(float v){for(int o=16;o;o>>=1)v+=__shfl_down_sync(0xffffffff,v,o);return v;}
__global__ void make_hidden(const uint16_t*g,const uint16_t*u,const float*x,float*h){__shared__ float gs[WARPS],us[WARPS];int row=blockIdx.x,l=threadIdx.x&31,w=threadIdx.x>>5;float a=0,b=0;for(int c=threadIdx.x;c<H;c+=blockDim.x){a=fmaf(bf(g[size_t(row)*H+c]),x[c],a);b=fmaf(bf(u[size_t(row)*H+c]),x[c],b);}a=ws(a);b=ws(b);if(!l){gs[w]=a;us[w]=b;}__syncthreads();if(!w){a=l<WARPS?gs[l]:0;b=l<WARPS?us[l]:0;a=ws(a);b=ws(b);if(!l)h[row]=(a/(1+expf(-a)))*b;}}
__global__ void down_partial(const uint16_t*d,const float*h,float*out){int l=threadIdx.x&31,w=threadIdx.x>>5,row=blockIdx.x*WARPS+w;if(row>=H)return;float sum=0;for(int c=l;c<S;c+=32)sum=fmaf(bf(d[size_t(row)*S+c]),h[c],sum);sum=ws(sum);if(!l)out[row]=sum;}
__global__ void shared_gate(const uint16_t*w,const float*x,float*scale){__shared__ float p[T];float s=0;for(int i=threadIdx.x;i<H;i+=blockDim.x)s=fmaf(bf(w[i]),x[i],s);p[threadIdx.x]=s;__syncthreads();for(int stride=blockDim.x/2;stride;stride>>=1){if(threadIdx.x<stride)p[threadIdx.x]+=p[threadIdx.x+stride];__syncthreads();}if(!threadIdx.x)scale[0]=1/(1+expf(-p[0]));}
Req rr(std::ifstream&f){Req r;uint32_t l;f.read((char*)&l,4);r.layer=l;r.x.resize(H);r.ids.resize(K);r.routes.resize(K);f.read((char*)r.x.data(),H*4);f.read((char*)r.ids.data(),K*4);f.read((char*)r.routes.data(),K*4);if(!f)throw 1;return r;}
#ifndef QWEN_M10_SHARED_LIBRARY_ONLY
int main(int ac,char**av){if(ac!=5){fprintf(stderr,"usage: multilayer_shared MANIFEST REQUESTS OUTPUT PARTIALS\n");return 2;}std::map<int,std::string>dirs;{std::ifstream f(av[1]);int l;std::string p;while(f>>l>>p){if(l<0||l>=48||dirs.count(l))return 2;dirs[l]=p;}}if(dirs.empty())return 2;std::ifstream f(av[2],std::ios::binary);uint32_t n;f.read((char*)&n,4);if(!f||!n||n>10000)return 2;std::vector<Req>req;for(unsigned i=0;i<n;i++){req.push_back(rr(f));if(!dirs.count(req.back().layer)){fprintf(stderr,"layer not READY\n");return 2;}}if(f.peek()!=EOF)return 2;int count;CK(cudaGetDeviceCount(&count));if(count!=4)return 2;std::vector<int>layers;std::map<int,size_t>idx;for(auto&x:dirs){idx[x.first]=layers.size();layers.push_back(x.first);}std::vector<std::vector<Weights>>all(layers.size(),std::vector<Weights>(4));std::vector<Work>w(4);
for(int d=0;d<4;d++){CK(cudaSetDevice(d));cudaDeviceProp p{};CK(cudaGetDeviceProperties(&p,d));if(p.major!=5||p.minor!=0)return 2;for(size_t li=0;li<layers.size();li++){char stem[32];snprintf(stem,sizeof(stem),"/shared.%d.",d);std::string b=dirs[layers[li]]+stem;auto&a=all[li][d];a.g=up(rf<uint16_t>(b+"gate.bin",size_t(S)*H));a.u=up(rf<uint16_t>(b+"up.bin",size_t(S)*H));a.d=up(rf<uint16_t>(b+"down.bin",size_t(H)*S));if(d==0)a.gate=up(rf<uint16_t>(dirs[layers[li]]+"/shared_gate_weight.bin",H));else a.gate=nullptr;}CK(cudaMalloc(&w[d].x,H*4));CK(cudaMalloc(&w[d].hidden,S*4));CK(cudaMalloc(&w[d].partial,H*4));if(!d)CK(cudaMalloc(&w[d].scale,4));else w[d].scale=nullptr;CK(cudaStreamCreate(&w[d].stream));size_t freeb,total;CK(cudaMemGetInfo(&freeb,&total));printf("SHARED_MULTILAYER_DEVICE,%d,layers,%zu,free,%zu,total,%zu\n",d,layers.size(),freeb,total);}
printf("SHARED_MULTILAYER_READY,layers,%zu\n",layers.size());std::vector<float>out(size_t(n)*H),parts(size_t(n)*4*H),scales(n);
for(unsigned r=0;r<n;r++){size_t li=idx[req[r].layer];for(int d=0;d<4;d++){CK(cudaSetDevice(d));auto&a=all[li][d];CK(cudaMemcpyAsync(w[d].x,req[r].x.data(),H*4,cudaMemcpyHostToDevice,w[d].stream));make_hidden<<<S,T,0,w[d].stream>>>(a.g,a.u,w[d].x,w[d].hidden);CK(cudaGetLastError());down_partial<<<(H+WARPS-1)/WARPS,T,0,w[d].stream>>>(a.d,w[d].hidden,w[d].partial);CK(cudaGetLastError());if(!d){shared_gate<<<1,T,0,w[d].stream>>>(a.gate,w[d].x,w[d].scale);CK(cudaGetLastError());}}for(int d=0;d<4;d++){CK(cudaSetDevice(d));CK(cudaStreamSynchronize(w[d].stream));CK(cudaMemcpy(parts.data()+(size_t(r)*4+d)*H,w[d].partial,H*4,cudaMemcpyDeviceToHost));if(!d)CK(cudaMemcpy(&scales[r],w[d].scale,4,cudaMemcpyDeviceToHost));}for(int j=0;j<H;j++){float sum=0;for(int d=0;d<4;d++)sum+=parts[(size_t(r)*4+d)*H+j];out[size_t(r)*H+j]=sum*scales[r];}printf("SHARED_MULTILAYER_REQUEST,%u,layer,%d,gate,%.9g\n",r,req[r].layer,scales[r]);}
{std::ofstream o(av[3],std::ios::binary);o.write((char*)out.data(),out.size()*4);} {std::ofstream o(av[4],std::ios::binary);o.write((char*)parts.data(),parts.size()*4);}for(int d=0;d<4;d++){CK(cudaSetDevice(d));CK(cudaFree(w[d].x));CK(cudaFree(w[d].hidden));CK(cudaFree(w[d].partial));if(w[d].scale)CK(cudaFree(w[d].scale));CK(cudaStreamDestroy(w[d].stream));for(size_t li=0;li<all.size();li++){auto&a=all[li][d];for(void*p:{(void*)a.g,(void*)a.u,(void*)a.d,(void*)a.gate})if(p)CK(cudaFree(p));}}puts("SHARED_MULTILAYER_STATUS,PASS");return 0;}
#endif
